#include <stdio.h>
#include <stdlib.h>

int countPrimes(int n) {
    if (n <= 2) return 0;
    unsigned char *isPrime = (unsigned char *)malloc((size_t)n);
    if (!isPrime) return 0;
    for (int i = 0; i < n; ++i) isPrime[i] = 1;
    isPrime[0] = isPrime[1] = 0;

    for (int p = 2; (long long)p * p < n; ++p) {
        if (isPrime[p]) {
            for (long long j = (long long)p * p; j < n; j += p)
                isPrime[j] = 0;
        }
    }

    int count = 0;
    for (int i = 2; i < n; ++i)
        if (isPrime[i]) ++count;

    free(isPrime);
    return count;
}

