class Solution {
    public int countPrimes(int n) {
        if (n <= 2) return 0;
        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        for (int p = 2; (long) p * p < n; p++) {
            if (isPrime[p]) {
                for (long j = (long) p * p; j < n; j += p)
                    isPrime[(int) j] = false;
            }
        }
        int count = 0;
        for (int i = 2; i < n; i++)
            if (isPrime[i]) count++;
        return count;
    }
}

